{#-
Updated march 10th 2026 by Diego Pino, changes from checking if its INT to NUMERIC. JSON can be encoded
as string from the webform
Updated march 6th 2026 by Diego Pino
- Part of "type" is dynamic based on the Parent Type now
- This adds a somehow complex logic that accumulates by "parent type" and avoid duplicated Parents BC
of the use of multiple predicates pointing to the same ID.
Note: to evaluate more predicates edit line 279, e.g {% set possible_predicates = ["ismemberof","ispartof","ismemberofseries"] %}

Updated 2026-01-29 to
- Added clamped transcript display preserving line breaks
- Transcript collapsed to 8 lines by default

Previously updated 2026-01-25 based on the general Object Description to be a better Episode/Segment Display 
Previously updated 23/10/2025 to add optional rich text support to html_output for Drupal
- Detects "value" property automatically (Drupal text fields)
- When rich = true, outputs HTML safely using |raw (Drupal already sanitizes)
Updated 15/02/2024 to add |striptags to html_output macro
Previously updated 31/10/2023 for 1.3.0
- switched to Macro approach; added Nav-tabs for main description display and downloads menu.
- MACROS:
  - uses two macros originally created by Diego,
  - uses two macros originally created by Allison for internal-search referenced elements
- File downloads nav-tab
-#}

{#- ------ CSS start ----- -#}

<style>
  /* Transcript clamping */
  .clamped-text {
    white-space: pre-line; /* preserves line breaks */
    overflow: hidden;
  }

  .clamped-text.collapsed {
    display: -webkit-box;
    -webkit-line-clamp: 8;
    -webkit-box-orient: vertical;
  }

  .clamp-toggle {
    margin-top: 0.5rem;
    background: none;
    border: none;
    padding: 0;
    cursor: pointer;
    font-size: 0.9rem;
  }
</style>

{#- ------ CSS end ----- -#}

{#- ------ Macros Start ----- -#}

{%- macro html_output(html_title, source_datum, list_wrapper = "p", markdown = false, rich = false) -%}
  {# Handle Drupal-style objects with a "value" property #}
  {%- if source_datum is iterable and 'value' in source_datum|keys -%}
    {%- set source_datum = source_datum.value -%}
  {%- endif -%}

  {# -- Macro note: if markdown is selected no wrapper will be used -#}
  {%- if source_datum and source_datum|length > 0 -%}
    {%- if html_title|length > 0 -%}
<h3>{{ html_title }}</h3>
    {%- endif -%}

    {%- if source_datum is iterable -%}
      {%- for source_data in source_datum -%}
        {%- if markdown -%}
          {{ source_data|markdown_2_html }}
        {%- else -%}
          {%- if rich -%}
            <{{ list_wrapper }}>{{ source_data|raw }}</{{ list_wrapper }}>
          {%- else -%}
            <{{ list_wrapper }}>{{ source_data|striptags }}</{{ list_wrapper }}>
          {%- endif -%}
        {%- endif -%}
      {%- endfor -%}
    {%- else -%}
      {%- if markdown -%}
        {{ source_datum|markdown_2_html }}
      {%- else -%}
        {%- if rich -%}
          {%- if list_wrapper|length > 0 -%}
            <{{ list_wrapper }}>{{ source_datum|raw }}</{{ list_wrapper }}>
          {%- else -%}
            {{ source_datum|raw }}
          {%- endif -%}
          {%- else -%}
          <{{ list_wrapper }}>{{ source_datum|striptags }}</{{ list_wrapper }}>
        {%- endif -%}
      {%- endif -%}
    {%- endif -%}
  {%- endif -%}
{%- endmacro html_output -%}

{# --- NEW: Dylan's clamped text macro (for transcripts) --- #}
{%- macro html_output_clamped(html_title, source_datum) -%}
  {# Handle Drupal-style objects with a "value" property #}
  {%- if source_datum is iterable and 'value' in source_datum|keys -%}
    {%- set source_datum = source_datum.value -%}
  {%- endif -%}

  {%- if source_datum and source_datum|length > 0 -%}
    {%- if html_title|length > 0 -%}
<h3>{{ html_title }}</h3>
    {%- endif -%}

<div class="clamped-text collapsed">
{{ source_datum|striptags }}
</div>

<button type="button"
        class="clamp-toggle"
        onclick="
          this.previousElementSibling.classList.toggle('collapsed');
          this.textContent = this.textContent === 'Show more'
            ? 'Show less'
            : 'Show more';
        ">
  Show more
</button>
  {%- endif -%}
{%- endmacro html_output_clamped -%}


{%- macro html_output_list(html_title, source_datum, markdown = false) -%}
  {# -- Macro note: if markdown is selected no wrapper will be used -#}
  {%- if source_datum and source_datum|length > 0 -%}
    {%- if html_title|length > 0 -%}
<h3>{{ html_title }}</h3>
    {%- endif -%}
  <ul>
    {%- if source_datum is iterable -%}
      {%- for source_data in source_datum -%}
        {%- if markdown -%}
          <li>{{ source_data|markdown_2_html }}</li>
        {%- else -%}
          <li>{{ source_data }}</li>
        {%- endif -%}
      {%- endfor -%}
    {%- else -%}
      {%- if markdown -%}
        <li>{{ source_datum|markdown_2_html }}</li>
      {%- else -%}
        <li>{{ source_datum }}</li>
      {%- endif -%}
    {%- endif -%}
  </ul>
  {%- endif -%}
{%- endmacro html_output_list -%}


{# Allison: internal search macros based off Diego's list output macro above;
added flag and formatting for internal search-based on value set within corresponding facet config;
one macro for simple non-LoD elements; second for LoD elements with URI and label values #}

{%- macro html_output_search(html_title, source_datum, search_facet) -%}
  {%- if source_datum and source_datum|length > 0 -%}
    {%- if html_title|length > 0 -%}
<h3>{{ html_title }}</h3>
    {%- endif -%}
  <ul>
    {%- if source_datum is iterable -%}
      {%- for source_data in source_datum -%}
        <li><a href="/search?search_api_fulltext=&f%5B0%5D={{ search_facet }}%3A{{ source_data|url_encode }}" target="_blank">{{ source_data }}</a></li>
      {%- endfor -%}
    {%- else -%}
      <li><a href="/search?search_api_fulltext=&f%5B0%5D={{ search_facet }}%3A{{ source_datum|url_encode }}" target="_blank">{{ source_datum }}</a></li>
    {%- endif -%}
  </ul>
  {%- endif -%}
{%- endmacro html_output_search -%}


{# Use for LoD elements with URI and label values #}
{%- macro html_output_search_lod(html_title, source_datum, search_facet) -%}
  {%- if source_datum and source_datum|length > 0 -%}
